  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: #0a0e1a;
  color: #e0e6ed;
  overflow-x: hidden;
}

.header {
  background: linear-gradient(135deg, #1a2332 0%, #2d3e50 100%);
  padding: 1.5rem 2rem;
