<body>

<div class="header">
  <h1>롯데월드타워 건축 설계 과정</h1>
  <div class="subtitle">서울 송파구 | 높이 555m, 지상 123층 | 설계: KPF | 구조: LERA</div>
  <div class="model-info">Powered by claude-sonnet-4.5</div>
</div>

<div class="container">
  <div class="panel">
    <h2>📐 설계 도면</h2>

    <div class="drawing-container">
      <div class="drawing-title">배치도 (Site Plan)</div>
      <canvas id="sitePlan" class="drawing-canvas"></canvas>
      <div class="info-box">
        <strong>축척:</strong> 1:2000 (개념도)<br>
        <strong>대지:</strong> 서울 송파구 올림픽로 300 일대<br>
        <strong>표시:</strong> 건물 위치, 주변 도로, 북측 방향
      </div>
    </div>

    <div class="drawing-container">
      <div class="drawing-title">기준층 평면도 (Typical Floor Plan)</div>
      <canvas id="floorPlan" class="drawing-canvas"></canvas>
      <div class="info-box">
        <strong>축척:</strong> 1:500 (개념도)<br>
        <strong>층:</strong> 중층부 기준층 예시<br>
        <strong>형태:</strong> 곡선형 외곽, 중앙 코어<br>
        <strong>치수:</strong> 공개 자료 기반 추정 (약 50-60m 직경)
      </div>
    </div>

    <div class="drawing-container">
      <div class="drawing-title">입면도 (Elevation)</div>
      <canvas id="elevation" class="drawing-canvas"></canvas>
      <div class="info-box">
        <strong>축척:</strong> 1:2000 (개념도)<br>
        <strong>높이:</strong> 555m (공식 자료)<br>
        <strong>층수:</strong> 지상 123층<br>
        <strong>특징:</strong> 상부로 갈수록 좁아지는 테이퍼 형태
      </div>
    </div>

    <div class="drawing-container">
      <div class="drawing-title">단면도 (Section)</div>
      <canvas id="section" class="drawing-canvas"></canvas>
      <div class="info-box">
        <strong>축척:</strong> 1:2000 (개념도)<br>
        <strong>구조:</strong> 메가 컬럼, 아웃리거 시스템 (LERA 설명 참고)<br>
        <strong>용도:</strong> 저층 상업, 중층 오피스, 상층 호텔/전망대<br>
        <strong>주의:</strong> 구조 부재 위치는 공개 자료 기반 추정
      </div>
    </div>

    <div class="note">
      <strong>⚠️ 중요:</strong> 이 도면들은 공개된 정보를 바탕으로 한 교육용 개념 재구성입니다. 
      공식 시공 도면이나 검증된 구조 설계가 아니며, 공개 자료에 없는 치수·단면·부재는 추정한 개념입니다.
    </div>
  </div>

  <div class="panel">
    <h2>🏗️ 설계 발전 과정</h2>

    <div class="stage-selector">
      <button class="stage-btn active" data-stage="0">1단계: 매스 스터디</button>
      <button class="stage-btn" data-stage="1">2단계: 형태 정제</button>
      <button class="stage-btn" data-stage="2">3단계: 외피 디자인</button>
      <button class="stage-btn" data-stage="3">4단계: 최종 설계</button>
    </div>

    <div class="stage-description" id="stageDesc">
      <strong>1단계: 매스 스터디</strong><br>
      기본적인 타워 형태를 결정하는 단계입니다. 높이 555m, 123층의 기본 볼륨을 설정하고, 
      상부로 갈수록 좁아지는 테이퍼 형태의 기본 비율을 연구합니다.
    </div>

    <h3>3D 모델 뷰어</h3>
    <canvas id="canvas3d"></canvas>

    <div class="controls">
      <button class="control-btn" id="resetView">🔄 시점 초기화</button>
      <button class="control-btn" id="toggleRotate">⏸️ 자동 회전</button>
      <button class="control-btn" id="topView">⬆️ 상부 뷰</button>
      <button class="control-btn" id="sideView">➡️ 측면 뷰</button>
    </div>

    <div class="legend">
      <div class="legend-item">
        <div class="legend-color" style="background: #4a9eff;"></div>
        <span>타워 본체</span>
      </div>
      <div class="legend-item">
        <div class="legend-color" style="background: #ff9a4a;"></div>
        <span>첨탑</span>
      </div>
      <div class="legend-item">
        <div class="legend-color" style="background: #6bff6b;"></div>
        <span>구조 요소</span>
      </div>
    </div>

    <div class="info-box">
      <strong>조작 방법:</strong><br>
      • 마우스 드래그 / 터치: 회전<br>
      • 마우스 휠 / 핀치: 확대/축소<br>
      • 우클릭 드래그 / 두 손가락: 이동<br>
      • 키보드: 화살표(회전), +/-(확대/축소), R(초기화)
    </div>

    <h3>설계 배경</h3>
    <div class="info-box">
      KPF는 롯데월드타워의 형태와 외관 디자인에 한국 전통 도자기의 우아한 곡선을 참고했다고 설명합니다. 
      건물은 지면에서 하늘로 올라가며 자연스럽게 가늘어지는 형태로, 
      이는 구조적 효율성과 미적 아름다움을 동시에 달성합니다.
    </div>

    <div class="sources">
      <strong>참고 자료:</strong><br>
      • 원 설계사: <a href="https://www.kpf.com/project/lotte-world-tower" target="_blank" rel="noopener">KPF - Lotte World Tower</a><br>
      • 구조 설계사: <a href="https://www.lera.com/lotte-world-tower" target="_blank" rel="noopener">LERA - Lotte World Tower</a>
    </div>
  </div>
</div>

<script>
// 전역 변수
let scene, camera, renderer, controls;
let currentStage = 0;
let autoRotate = true;
let towerModels = [];

// 설계 단계 설명
const stageDescriptions = [
  {
    title: "1단계: 매스 스터디",
    desc: "기본적인 타워 형태를 결정하는 단계입니다. 높이 555m, 123층의 기본 볼륨을 설정하고, 상부로 갈수록 좁아지는 테이퍼 형태의 기본 비율을 연구합니다."
  },
  {
    title: "2단계: 형태 정제",
    desc: "한국 도자기의 곡선미를 반영하여 건물의 윤곽을 부드럽게 다듬습니다. 각 층의 면적 변화율을 조정하고, 구조적 안정성을 고려한 형태를 확정합니다."
  },
  {
    title: "3단계: 외피 디자인",
    desc: "유리 커튼월 시스템을 적용하고, 건물 표면의 패턴과 질감을 디자인합니다. 채광과 에너지 효율을 고려한 외피 시스템을 개발합니다."
  },
  {
    title: "4단계: 최종 설계",
    desc: "모든 요소를 통합한 최종 설계안입니다. 첨탑, 조명, 구조 시스템이 완성되어 실제 시공 가능한 형태로 완성됩니다."
  }
];

// 도면 그리기 함수들
function drawSitePlan() {
  const canvas = document.getElementById('sitePlan');
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;

  canvas.width = canvas.offsetWidth * dpr;
  canvas.height = 400 * dpr;
  canvas.style.height = '400px';
  ctx.scale(dpr, dpr);

  const w = canvas.offsetWidth;
  const h = 400;

  // 배경
  ctx.fillStyle = '#0a0e1a';
  ctx.fillRect(0, 0, w, h);

  // 그리드
  ctx.strokeStyle = '#1a2332';
  ctx.lineWidth = 1;
  for (let i = 0; i < w; i += 40) {
    ctx.beginPath();
    ctx.moveTo(i, 0);
    ctx.lineTo(i, h);
    ctx.stroke();
  }
  for (let i = 0; i < h; i += 40) {
    ctx.beginPath();
    ctx.moveTo(0, i);
    ctx.lineTo(w, i);
    ctx.stroke();
  }

  // 북측 표시
  ctx.fillStyle = '#6b7c93';
  ctx.font = '14px sans-serif';
  ctx.fillText('N ↑', 20, 30);

  // 주변 도로
  ctx.strokeStyle = '#4a5568';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(0, h * 0.3);
  ctx.lineTo(w, h * 0.3);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(w * 0.2, 0);
  ctx.lineTo(w * 0.2, h);
  ctx.stroke();

  ctx.fillStyle = '#6b7c93';
  ctx.font = '12px sans-serif';
  ctx.fillText('올림픽로', w * 0.5, h * 0.3 - 10);

  // 건물 위치
  const centerX = w * 0.5;
  const centerY = h * 0.6;
  const buildingSize = 60;

  ctx.fillStyle = '#4a9eff';
  ctx.fillRect(centerX - buildingSize/2, centerY - buildingSize/2, buildingSize, buildingSize);

  ctx.strokeStyle = '#6ba3ff';
  ctx.lineWidth = 2;
  ctx.strokeRect(centerX - buildingSize/2, centerY - buildingSize/2, buildingSize, buildingSize);

  ctx.fillStyle = '#fff';
  ctx.font = 'bold 14px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('롯데월드타워', centerX, centerY);

  // 주변 건물들 (개념)
  ctx.fillStyle = '#2d3e50';
  ctx.fillRect(w * 0.15, h * 0.5, 30, 40);
  ctx.fillRect(w * 0.75, h * 0.45, 35, 50);
  ctx.fillRect(w * 0.6, h * 0.75, 25, 30);

  // 축척 표시
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(20, h - 30);
  ctx.lineTo(120, h - 30);
  ctx.stroke();

  ctx.fillStyle = '#fff';
  ctx.font = '11px sans-serif';
  ctx.textAlign = 'left';
  ctx.fillText('0', 20, h - 35);
  ctx.fillText('200m', 115, h - 35);
  ctx.fillText('(개념 축척)', 20, h - 15);
}

function drawFloorPlan() {
  const canvas = document.getElementById('floorPlan');
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;

  canvas.width = canvas.offsetWidth * dpr;
  canvas.height = 400 * dpr;
  canvas.style.height = '400px';
  ctx.scale(dpr, dpr);

  const w = canvas.offsetWidth;
  const h = 400;

  ctx.fillStyle = '#0a0e1a';
  ctx.fillRect(0, 0, w, h);

  const centerX = w / 2;
  const centerY = h / 2;
  const radius = Math.min(w, h) * 0.35;

  // 외곽 (곡선형)
  ctx.strokeStyle = '#4a9eff';
  ctx.lineWidth = 3;
  ctx.beginPath();
  for (let i = 0; i <= 360; i += 5) {
    const angle = (i * Math.PI) / 180;
    const r = radius * (1 + 0.1 * Math.sin(angle * 3));
    const x = centerX + r * Math.cos(angle);
    const y = centerY + r * Math.sin(angle);
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.stroke();

  ctx.fillStyle = 'rgba(74, 158, 255, 0.1)';
  ctx.fill();

  // 중앙 코어
  const coreRadius = radius * 0.3;
  ctx.fillStyle = '#2d3e50';
  ctx.beginPath();
  ctx.arc(centerX, centerY, coreRadius, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = '#6ba3ff';
  ctx.lineWidth = 2;
  ctx.stroke();

  ctx.fillStyle = '#a8b8cc';
  ctx.font = '12px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('코어', centerX, centerY - 10);
  ctx.fillText('(엘리베이터,', centerX, centerY + 5);
  ctx.fillText('계단, 설비)', centerX, centerY + 20);

  // 기둥 위치 (추정)
  const columnPositions = [0, 60, 120, 180, 240, 300];
  ctx.fillStyle = '#6bff6b';
  columnPositions.forEach(angle => {
    const rad = (angle * Math.PI) / 180;
    const colRadius = radius * 0.6;
    const x = centerX + colRadius * Math.cos(rad);
    const y = centerY + colRadius * Math.sin(rad);
    ctx.beginPath();
    ctx.arc(x, y, 6, 0, Math.PI * 2);
    ctx.fill();
  });

  // 치수선
  ctx.strokeStyle = '#ff9a4a';
  ctx.lineWidth = 1;
  ctx.setLineDash([5, 5]);
  ctx.beginPath();
  ctx.moveTo(centerX - radius * 1.1, centerY);
  ctx.lineTo(centerX + radius * 1.1, centerY);
  ctx.stroke();

  ctx.setLineDash([]);
  ctx.fillStyle = '#ff9a4a';
  ctx.font = '11px sans-serif';
  ctx.fillText('≈ 50-60m (추정)', centerX, centerY - radius * 1.15);

  // 범례
  ctx.textAlign = 'left';
  ctx.fillStyle = '#6bff6b';
  ctx.beginPath();
  ctx.arc(20, h - 60, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#a8b8cc';
  ctx.font = '11px sans-serif';
  ctx.fillText('구조 기둥 (추정 위치)', 30, h - 56);

  ctx.fillStyle = '#2d3e50';
  ctx.fillRect(20, h - 40, 10, 10);
  ctx.fillStyle = '#a8b8cc';
  ctx.fillText('중앙 코어', 35, h - 32);
}

function drawElevation() {
  const canvas = document.getElementById('elevation');
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;

  canvas.width = canvas.offsetWidth * dpr;
  canvas.height = 500 * dpr;
  canvas.style.height = '500px';
  ctx.scale(dpr, dpr);

  const w = canvas.offsetWidth;
  const h = 500;

  ctx.fillStyle = '#0a0e1a';
  ctx.fillRect(0, 0, w, h);

  // 지면
  ctx.strokeStyle = '#4a5568';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(0, h - 50);
  ctx.lineTo(w, h - 50);
  ctx.stroke();

  ctx.fillStyle = '#6b7c93';
  ctx.font = '12px sans-serif';
